links=[]
def link(kind,src,dst,what,evidence,ii=()):
 notes=[]
 for i in ii:
  for n in I[i]['sources']:
   if n not in notes:notes.append(n)
 links.append({'kind':kind,'from':src,'to':dst,'what':what,'evidence':evidence,'note_ids':'; '.join(notes)})
