def write(name,rows,fields):
 with (P/name).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=fields,delimiter='\t');w.writeheader();w.writerows(rows)
if __name__=='__main__':
 write('readings.tsv',readings,['cote','scan','line','reading','alternative','evidence','weight','confidence'])
 write('links.tsv',links,['kind','from','to','what','evidence','note_ids'])
 write('our_projects.tsv',[x for x in links if x['kind']=='our projects'],['kind','from','to','what','evidence','note_ids'])
 print(json.dumps({'readings':len(readings),'links':len(links),'project_leads':sum(x['kind']=='our projects' for x in links)}))
